///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fnSearch_ajaxsubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/listinvstg/listcomdetail.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jlddst70010.tx_fnSearch_ajaxsubmit" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.fnPopClose
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnPopClose = function () {
    /* sdd-asis-lifecycle:begin fnPopClose — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnInit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnInit = async function () {
    /* sdd-asis-lifecycle:begin fnInit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await scwin.fnTabMenu("0");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnTabMenu
 * @author Inswave
 * @date 2026. 09. 29
 * @param menuIdx
 * @returns
 * @hidden N
*/
scwin.fnTabMenu = async function (menuIdx) {
    /* sdd-asis-lifecycle:begin fnTabMenu — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $(document).find("li[id=tabName]").each(function(index) {
            if ($(this).hasClass("active")) {
                $(this).removeClass("active");
            }
            if (index === menuIdx) {
                $(this).addClass("active");
            }
    });
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("menuIndex", menuIdx);
    await scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const vMenuIndex = ($c.util.getComponent("dma_fnSearchAjaxsubmitReq").get("menuIndex") || '');
    let vMethod = "";
    if (vMenuIndex === "0") {
        vMethod = "searchListComOvrvwDetail";
    } else {
        if (vMenuIndex === "1") {
            vMethod = "searchListComFncContnDetail";
        } else {
            if (vMenuIndex === "2") {
                vMethod = "searchListComPubofrDetail";
            } else {
                return;
            }
        }
    }
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("method", vMethod);
    await scwin.tx_fnSearch_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCallBack
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.fnSearchCallBack = function (data) {
    /* sdd-asis-lifecycle:begin fnSearchCallBack — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("#tabContents").empty().append(data);
    /* sdd-asis-lifecycle:end */
};
